def transform(grid):
    from collections import Counter, defaultdict

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return [row[:] for row in grid]
    frame = counts.most_common(1)[0][0]

    # Find each separated nonzero tile.
    seen = set()
    tiles = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            features = defaultdict(set)
            for y, x in cells:
                if grid[y][x] != frame:
                    features[grid[y][x]].add((y - r0, x - c0))
            tiles.append((r0, r1, c0, c1, features))

    feature_counts = Counter()
    for tile in tiles:
        for color, cells in tile[4].items():
            feature_counts[color] += len(cells)
    if not feature_counts:
        return [row[:] for row in grid]
    common = feature_counts.most_common(1)[0][0]

    out = [row[:] for row in grid]

    # Connect consecutive occurrences of each non-common feature color.
    rows = defaultdict(list)
    cols = defaultdict(list)
    for tile in tiles:
        r0, r1, c0, c1, features = tile
        for color, cells in features.items():
            if color != common:
                rows[r0].append(tile)
                cols[c0].append(tile)
                break

    for group in rows.values():
        group.sort(key=lambda t: t[2])
        for i, a in enumerate(group):
            for b in group[i + 1:]:
                if a[0] != b[0]:
                    continue
                for color in set(a[4]) & set(b[4]):
                    if color == common:
                        continue
                    for lr, lc in a[4][color] & b[4][color]:
                        for x in range(a[3] + 1, b[2]):
                            if out[a[0] + lr][x] == 0:
                                out[a[0] + lr][x] = color

    for group in cols.values():
        group.sort(key=lambda t: t[0])
        for i, a in enumerate(group):
            for b in group[i + 1:]:
                if a[2] != b[2]:
                    continue
                for color in set(a[4]) & set(b[4]):
                    if color == common:
                        continue
                    for lr, lc in a[4][color] & b[4][color]:
                        for y in range(a[1] + 1, b[0]):
                            if out[y][a[2] + lc] == 0:
                                out[y][a[2] + lc] = color

    return out
